-- =========================================================================
-- Cat A — Renommage (2 UPDATE) : aligner DB sur frontend
-- =========================================================================

-- F-DT-17 : ordre des mots inversé entre back et front
UPDATE decision_tool_visibility_rules
SET tool_id = 'F-DT-17-indemnite-precarite-cdd'
WHERE tool_id = 'F-DT-17-cdd-indemnite-precarite';

-- F-DT-35 : suffixe `-fr` côté frontend
UPDATE decision_tool_visibility_rules
SET tool_id = 'F-DT-35-contestation-are-fr'
WHERE tool_id = 'F-DT-35-contestation-are';

-- =========================================================================
-- Cat C — DELETE (11) : tool_id sans composant frontend auto-suffisant au 2026-04-26.
-- Les services backend (calculators, controllers, tables d'analyses)
-- continuent d'exister pour les outils qui en ont un — seul l'aiguillage
-- F-IA-04 est désactivé tant que le composant frontend n'est pas livré.
-- =========================================================================

DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-DT-01-calcul-indemnite-simple';
DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-DT-05-preavis-be';
DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-FA-01-prestation-compensatoire';
DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-FA-02-pension-alimentaire';
DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-FA-04-liquidation-communaute';
DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-FA-18-adoption';
DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-FA-24-indivision-successorale';
DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-FA-24-partage-successoral';
DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-FA-24-rapport-succession';
DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-152-divorce-consentement-scoring';
DELETE FROM decision_tool_visibility_rules WHERE tool_id = 'F-153-fourchettes-jaf';
